-- Backfill:
-- UPDATE invoices SET invoice_date = created_at::date WHERE invoice_date IS NULL;

ALTER TABLE invoices ADD COLUMN IF NOT EXISTS payment_terms TEXT;
-- "Net 14", "Net 30", "Due on receipt", etc.

